    pub fn set_materials(&mut self, materials: MaterialSet) {
        self.materials = materials;
        let capacity = self.materials.len();
        for object in &mut self.objects {
            object.ensure_material_capacity(capacity);
        }
        if let Some(landscape) = self.landscape.as_mut() {
            let default = self.materials.default_ground_material();
            landscape.set_default_solid_material(default);
        }
    }

    pub fn materials(&self) -> &MaterialSet {
        &self.materials
    }

    pub fn materials_mut(&mut self) -> &mut MaterialSet {
        &mut self.materials
    }

    fn materials_shared(&self) -> Rc<MaterialSet> {
        let mut cache = self.materials_shared.borrow_mut();
        match cache.as_ref() {
            Some(shared) => Rc::clone(shared),
            None => {
                let shared = Rc::new(self.materials.clone());
                *cache = Some(Rc::clone(&shared));
                shared
            }
        }
    }

    pub fn configure_materials_from_library(&mut self, library: &lc_resources::MaterialLibrary) {
        self.materials_shared.borrow_mut().take();
        self.materials = MaterialSet::from_resource_library(library);
        let capacity = self.materials.len();
        for object in &mut self.objects {
            object.ensure_material_capacity(capacity);
        }
    }

    pub fn frame(&self) -> u64 {
        self.frame
    }

    pub fn game_time(&self) -> i32 {
        self.game_time
    }

    /// `C4Game::Sec1Timer`: consume the per-frame TimeGo latch and advance
    /// the real game clock at most once (`C4Game.cpp:1755-1759`).
    pub fn sec1_timer(&mut self) {
        if std::mem::take(&mut self.time_go) {
            self.game_time = self.game_time.wrapping_add(1);
        }
    }

    fn assign_player_info_id(&mut self, requested: i32) -> i32 {
        if requested == 0 {
            self.last_player_info_id = self.last_player_info_id.wrapping_add(1);
            self.last_player_info_id
        } else {
            self.last_player_info_id = self.last_player_info_id.max(requested);
            requested
        }
    }

    pub fn configure_objectives(&mut self, objectives: ScenarioObjectives) {
        self.objectives = objectives;
        self.objective_check_counter = GAME_OVER_CHECK_INTERVAL.saturating_sub(1);
    }

    pub fn set_landscape(&mut self, mut landscape: Landscape) {
        let default = self.materials.default_ground_material();
        if default.is_some() {
            landscape.set_default_solid_material(default);
        }
        // UpdatePixMaps (C4Landscape.cpp:2832-2839): resolve the grid's
        // texmap material names into engine ids now that both exist.
        let materials = &self.materials;
        landscape.resolve_grid_materials(|name| materials.id_of(name));
        // MVehic (C4Game::InitMaterialTexture, C4Game.cpp:1669): the
        // closed-border material for GetPix's MCVehic reads.
        landscape.set_vehicle_material(materials.id_of("Vehicle"));
        self.landscape = Some(landscape);
        self.reset_sectors_from_landscape();
    }

    pub fn blast_circle(
        &mut self,
        center: Vector2,
        radius: i32,
        controller: Option<i32>,
    ) -> Option<BlastResult> {
        if radius < 0 {
            return None;
        }
        let has_pixel_grid = self.landscape.as_ref()?.pixel_grid().is_some();
        let result = if has_pixel_grid {
            self.blast_raster_circle(center, radius)
        } else {
            let result = {
                let landscape = self.landscape.as_mut()?;
                landscape.blast_circle(center, radius, &self.materials)
            };
            if !result.shift_candidates.is_empty() {
                self.apply_blast_shifts(radius, &result);
            }
            // Column-only fixture worlds cannot interleave their approximate
            // clears with C++'s per-pixel instability probes. Retain the old
            // post-pass for that synthetic fallback only.
            for ycnt in -radius..=radius {
                let remaining = i64::from(radius) * i64::from(radius)
                    - i64::from(ycnt) * i64::from(ycnt);
                let lwdt = (remaining as f64).sqrt() as i32;
                let dpy = center.y + ycnt;
                for xcnt in -lwdt..lwdt + i32::from(lwdt == 0) {
                    self.check_instability_range(center.x + xcnt, dpy);
                }
            }
            result
        };
        // The evaluate loop keys on the PRE-blast BlastMatCount, not on
        // what was removed (C4Landscape.cpp:1065-1079).
        if !result.pixel_count_by_material.is_empty() {
            self.process_blast_reactions(center, controller, &result);
        }
        Some(result)
    }

    /// C4Landscape::BlastFree / BlastFreePix on the authoritative Surface8
    /// plane (C4Landscape.cpp:941-960,1022-1063): count the complete circle
    /// first, then revisit every pixel in the same order. BlastShiftTo draws
    /// once PER source pixel, writes while retaining IFT, BlastFree clears
    /// based on the original material, and instability is probed immediately.
    fn blast_raster_circle(&mut self, center: Vector2, radius: i32) -> BlastResult {
        let mut result = BlastResult::default();
        for ycnt in -radius..=radius {
            let remaining = i64::from(radius) * i64::from(radius)
                - i64::from(ycnt) * i64::from(ycnt);
            let lwdt = (remaining as f64).sqrt() as i32;
            let y = center.y + ycnt;
            for xcnt in -lwdt..lwdt + i32::from(lwdt == 0) {
                let x = center.x + xcnt;
                if let Some(material) = self
                    .landscape
                    .as_ref()
                    .and_then(|landscape| landscape.material_at(x, y))
                {
                    *result
                        .pixel_count_by_material
                        .entry(material)
                        .or_insert(0) += 1;
                }
            }
        }

        let blast_size = compute_blast_size(radius);
        let grade = compute_blast_grade(radius);
        let shift_threshold = (blast_size * grade) / 6;
        let mut changed_columns = HashSet::new();
        for ycnt in -radius..=radius {
            let remaining = i64::from(radius) * i64::from(radius)
                - i64::from(ycnt) * i64::from(ycnt);
            let lwdt = (remaining as f64).sqrt() as i32;
            let y = center.y + ycnt;
            for xcnt in -lwdt..lwdt + i32::from(lwdt == 0) {
                let x = center.x + xcnt;
                let material = self
                    .landscape
                    .as_ref()
                    .and_then(|landscape| landscape.material_at(x, y));
                if let Some(material) = material {
                    let (blast_free, shift_spec, shift_target) = self
                        .materials
                        .get_by_id(material)
                        .map(|entry| {
                            (
                                entry.blast_free(),
                                entry.blast_shift_to_spec().map(str::to_owned),
                                entry.blast_shift_to_target(),
                            )
                        })
                        .unwrap_or((false, None, None));
                    let shift_byte = shift_spec
                        .as_deref()
                        .zip(shift_target)
                        .and_then(|(spec, fallback)| {
                            self.landscape.as_ref().and_then(|landscape| {
                                landscape.material_texture_byte(spec, fallback)
                            })
                        });
                    if let Some(shift_byte) = shift_byte {
                        let material_count = result
                            .pixel_count_by_material
                            .get(&material)
                            .copied()
                            .unwrap_or(0);
                        if i64::from(self.rng.random(material_count)) < shift_threshold {
                            let shifted = self.landscape.as_mut().is_some_and(|landscape| {
                                landscape.insert_material_texture_pix(x, y, shift_byte)
                            });
                            if shifted {
                                changed_columns.insert(x);
                            }
                        }
                    }
                    if blast_free
                        && self
                            .landscape
                            .as_mut()
                            .is_some_and(|landscape| landscape.clear_pix(x, y))
                    {
                        *result.removed_by_material.entry(material).or_insert(0) += 1;
                        changed_columns.insert(x);
                    }
                }
                self.check_instability_range(x, y);
            }
        }

        if let Some((width, _)) = self
            .landscape
            .as_ref()
            .and_then(Landscape::grid_dimensions)
        {
            let start = center.x.saturating_sub(radius).clamp(0, width) as usize;
            let end = center
                .x
                .saturating_add(radius)
                .saturating_add(1)
                .clamp(0, width) as usize;
            if let Some(landscape) = self.landscape.as_mut() {
                landscape.refresh_raster_columns(start..end);
                for x in start..end {
                    let x = x as i32;
                    if changed_columns.contains(&x) {
                        if let Some(surface) = landscape.surface_height(x) {
                            result.affected_columns.push((x, surface));
                        }
                    }
                }
            }
        }
        result
    }

    pub fn clear_landscape(&mut self) {
        self.landscape = None;
        self.sectors = None;
        self.pxs_system.clear();
    }

    pub fn landscape(&self) -> Option<&Landscape> {
        self.landscape.as_ref()
    }

    fn reset_sectors_from_landscape(&mut self) {
        let Some(landscape) = self.landscape.as_ref() else {
            self.sectors = None;
            return;
        };
        let width = saturating_u64_to_i32(u64::from(landscape.width()));
        let height = landscape.estimated_height();
        self.sectors = Some(SectorMap::new(width, height));
        self.rebuild_sectors();
    }

    fn rebuild_sectors(&mut self) {
        // C4LSectors::Add receives the main-list order. `exec_list` stores
        // that list reversed, so rebuild each sector front-to-back here;
        // SetObjectOrder's UpdatePosResort must change area traversal too
        // (C4GameObjects.cpp:739-769).
        let mut seen = HashSet::with_capacity(self.objects.len());
        let mut records = Vec::with_capacity(self.objects.len());
        for &id in self.exec_list.iter().rev() {
            let Some(index) = self.find_object_index(id) else {
                continue;
            };
            seen.insert(id);
            if let Some(record) = self.sector_record_for_object(&self.objects[index]) {
                records.push(record);
            }
        }
        records.extend(
            self.objects
                .iter()
                .filter(|object| seen.insert(object.id))
                .filter_map(|object| self.sector_record_for_object(object)),
        );
        if let Some(sectors) = self.sectors.as_mut() {
            sectors.rebuild(records);
        }
    }

    fn update_sector_for_index(&mut self, index: usize) {
        let Some(object) = self.objects.get(index) else {
            return;
        };
        let object_id = object.id;
        let record = self.sector_record_for_object(object);
        let Some(sectors) = self.sectors.as_mut() else {
            return;
        };
        match record {
            Some(record) => sectors.update(record),
            None => sectors.remove(object_id),
        }
    }

    fn sector_record_for_object(&self, object: &Object) -> Option<SectorObject> {
        if object.destroyed || matches!(object.state.status, ObjectStatus::Deleted) {
            return None;
        }
        let position = object.state.position;
        let shape_rect = self.object_shape_rect(object);
        Some(SectorObject {
            id: object.id,
            position,
            shape_rect,
        })
    }

    fn object_shape_rect(&self, object: &Object) -> DefinitionRect {
        let position = object.state.position;
        let mut rect = object
            .current_shape_rect()
            .map(|rect| {
                DefinitionRect::new(
                    position.x.saturating_add(rect.x),
                    position.y.saturating_add(rect.y),
                    rect.width,
                    rect.height,
                )
            })
            .or_else(|| vertex_bounds_rect(position, &object.state.vertices))
            .unwrap_or_else(|| DefinitionRect::new(position.x, position.y, 1, 1));
        // C4Object::Top/Height and At expand short construction shapes
        // upward to an 18-pixel action area (C4Object.h:340-344;
        // C4Object.cpp:1124-1140). C4LArea::Set uses those same accessors,
        // so sector ObjectShapes membership must include the expansion too.
        let add_top = (18 - rect.height).max(0);
        rect.y = rect.y.saturating_sub(add_top);
        rect.height = rect.height.saturating_add(add_top);
        rect
    }

    fn object_entrance_area(&self, object: &Object) -> Option<DefinitionRect> {
        if object.state.ocf & crate::ocf::ENTRANCE == 0 {
            return None;
        }
        let entrance = self
            .definitions
            .get(&object.definition_id)?
            .entrance_rect()?;
        Some(DefinitionRect::new(
            object.state.position.x.saturating_add(entrance.x),
            object.state.position.y.saturating_add(entrance.y),
            entrance.width,
            entrance.height,
        ))
    }

    #[allow(dead_code)]
    #[doc(hidden)]
    pub fn at_object(
        &self,
        point: Vector2,
        mask: u32,
        exclude: Option<ObjectId>,
    ) -> Option<(usize, ObjectId, u32)> {
        let candidate_ids = self
            .sectors
            .as_ref()
            // C4GameObjects::ObjectsAt returns this sector's ObjectShapes,
            // not its center-point Objects list (C4GameObjects.cpp:87-90).
            .map(|sectors| sectors.shape_ids_at(point.x, point.y).to_vec())
            .unwrap_or_else(|| self.objects.iter().map(|object| object.id).collect());
        for candidate_id in candidate_ids {
            if exclude == Some(candidate_id) {
                continue;
            }
            let Some(candidate_idx) = self.find_object_index(candidate_id) else {
                continue;
            };
            let candidate = &self.objects[candidate_idx];
            if candidate.destroyed
                || !candidate.state.status.is_active()
                || candidate.state.container.is_some()
            {
                continue;
            }
            let candidate_ocf = self.object_ocf_at_index(candidate_idx);
            if candidate_ocf & (mask | crate::ocf::EXCLUSIVE) == 0 {
                continue;
            }
            if !self
                .object_shape_rect(candidate)
                .contains_point(point.x, point.y)
            {
                continue;
            }
            // GetOCFForPos (C4Object.cpp:1146-1160): the returned mask
            // keeps Entrance/Collection only inside their def areas.
            let candidate_ocf = self.object_ocf_for_pos(candidate_idx, point);
            if candidate_ocf & mask != 0 {
                return Some((candidate_idx, candidate_id, candidate_ocf));
            }
            return None;
        }
        None
    }

    /// `C4Object::GetOCFForPos` (C4Object.cpp:1146-1160): the cached mask
    /// with OCF_Entrance/OCF_Collection verified against the def's
    /// Entrance/Collection areas at the probe point.
    pub(crate) fn object_ocf_for_pos(&self, index: usize, point: Vector2) -> u32 {
        let object = &self.objects[index];
        let mut rocf = object.state.ocf;
        if rocf & (crate::ocf::ENTRANCE | crate::ocf::COLLECTION) == 0 {
            return rocf;
        }
        let definition = self.definitions.get(&object.definition_id);
        let position = object.state.position;
        let inside_area = |rect: Option<DefinitionRect>| {
            rect.is_some_and(|rect| {
                let dx = point.x - (position.x + rect.x);
                let dy = point.y - (position.y + rect.y);
                (0..rect.width).contains(&dx) && (0..rect.height).contains(&dy)
            })
        };
        // Verify entrance area (C4Object.cpp:1149-1153)
        if rocf & crate::ocf::ENTRANCE != 0
            && !inside_area(definition.and_then(|definition| definition.entrance_rect()))
        {
            rocf &= !crate::ocf::ENTRANCE;
        }
        // Verify collection area (C4Object.cpp:1154-1158)
        if rocf & crate::ocf::COLLECTION != 0
            && !inside_area(definition.and_then(|definition| definition.collection_rect()))
        {
            rocf &= !crate::ocf::COLLECTION;
        }
        rocf
    }

    pub fn find_path(
        &self,
        from: Vector2,
        to: Vector2,
        level: i32,
        transfer_zones_enabled: bool,
    ) -> Option<pathfinder::Path> {
        let landscape = self.landscape.as_ref()?;
        let zones = self.transfer_zones.states();
        let mut finder = PathFinder::new(landscape, &zones);
        finder.set_level(level);
        finder.enable_transfer_zones(transfer_zones_enabled);
        finder.find(from, to)
    }

    pub fn physics(&self) -> PhysicsSettings {
        self.physics
    }

    /// Register a particle definition, mirroring `C4ParticleDef::Load`
    /// (C4Particles.cpp:118-192). `gfx_length` is the number of animation
    /// phases in the graphics, `aspect` the phase height:width ratio — both
    /// derived from Graphics.png at load time in C++.
    pub fn register_particle_definition(
        &mut self,
        core: particles::ParticleDefCore,
        gfx_length: i32,
        aspect: f32,
    ) -> Result<(), particles::ParticleDefError> {
        self.particle_system.register_def(core, gfx_length, aspect)
    }

    pub fn particle_system(&self) -> &particles::ParticleSystem {
        &self.particle_system
    }

    pub fn set_physics(&mut self, physics: PhysicsSettings) {
        self.physics = physics;
        for object in &mut self.objects {
            object.clamp_velocity(&self.physics);
        }
    }

    pub fn set_network_game(&mut self, network_game: bool) {
        self.network_game = network_game;
    }

    pub fn set_local_players<I>(&mut self, players: I)
    where
        I: IntoIterator<Item = i32>,
    {
        self.local_players = Some(players.into_iter().collect());
    }

    pub fn environment(&self) -> EnvironmentSettings {
        self.environment
    }

    /// The nine raw Game.GraphicsSystem.dwGamma controls. Applying these to
    /// the renderer LUT is deliberately outside this engine-state slice.
    pub fn gamma_controls(&self) -> &GammaControlState {
        &self.gamma
    }

    /// Add the nine controls exactly like C4GraphicsSystem::ApplyGamma
    /// (C4GraphicsSystem.cpp:787-809), returning its three packed RGB points.
    pub fn effective_gamma_control_points(&self) -> [u32; 3] {
        self.gamma.combined_control_points()
    }

    /// C4GraphicsSystem::Default (C4GraphicsSystem.cpp:277-281), used at a
    /// fresh scenario boundary before its Initialize script may set slot 0.
    pub(crate) fn reset_gamma_controls(&mut self) {
        self.gamma = GammaControlState::default();
    }

    /// C4Weather::SetSeasonGamma writes the weather curve into
    /// C4GRI_SEASON (slot 1) and leaves the existing slot untouched when
    /// NoGamma is set (C4Weather.cpp:259-284).
    fn refresh_season_gamma_control(&mut self) {
        if let Some(points) = self.environment.season_gamma_control_points() {
            let _ = self.gamma.set_ramp(1, points);
        }
    }

    fn apply_environment_delta(&mut self, delta: &EnvironmentDelta) {
        let refresh_gamma = delta.requests_season_gamma_refresh();
        delta.apply(&mut self.environment);
        if refresh_gamma {
            self.refresh_season_gamma_control();
        }
    }

    pub fn set_environment(&mut self, environment: EnvironmentSettings) {
        let mut environment = environment;
        environment.refresh_runtime_fields();
        self.environment = environment;
    }

    pub fn set_sky(&mut self, settings: SkySettings) {
        self.sky = Some(SkyState::new(settings));
    }

    pub fn clear_sky(&mut self) {
        self.sky = None;
    }

    pub fn sky_settings(&self) -> Option<&SkySettings> {
        self.sky.as_ref().map(SkyState::settings)
    }

    pub fn team_home_base_rule(&self) -> bool {
        self.team_home_base_rule
    }

    pub fn set_team_home_base_rule(&mut self, enabled: bool) {
        if self.team_home_base_rule == enabled {
            return;
        }
        self.team_home_base_rule = enabled;
        if enabled {
            let ids: Vec<_> = self.players.keys().copied().collect();
            for id in ids {
                self.sync_team_home_base_for(id);
            }
        }
    }

    fn definition_metadata_table(&self) -> Rc<HashMap<DefinitionId, DefinitionMetadata>> {
        let mut cache = self.definition_metadata_cache.borrow_mut();
        if let Some(table) = cache.as_ref() {
            return Rc::clone(table);
        }
        let table: Rc<HashMap<DefinitionId, DefinitionMetadata>> = Rc::new(
            self.definitions
                .iter()
                .map(|(id, definition)| {
                    (
                        id.clone(),
                        DefinitionMetadata {
                            name: definition.name().to_string(),
                            portrait_names: definition
                                .portrait_graphics_names()
                                .map(str::to_string)
                                .collect(),
                            category: definition.category(),
                            blit_mode: definition.blit_mode(),
                            ocf_base: definition.ocf_base(),
                            crew_member: definition.is_crew(),
                            action_library: definition.action_library().clone(),
                            action_graphics: definition.action_graphics().clone(),
                            value: definition.value(),
                            mass: definition.mass(),
                            constructable: definition.is_constructable(),
                            shape: definition.shape_rect(),
                            placement: definition.placement(),
                            growth: definition.growth(),
                            construction_offset: definition.construction_offset(),
                            basement: definition.basement(),
                            physical: *definition.physical(),
                            components: definition
                                .components()
                                .iter()
                                .map(|component| {
                                    (component.id.as_str().to_string(), component.count)
                                })
                                .collect(),
                            line_connect: definition.line_connect(),
                            stretch_growth: definition.stretch_growth(),
                            rotateable: definition.rotateable(),
                            line: definition.line(),
                            vertices: definition.shape_vertices().to_vec(),
                            contact_density: Some(definition.contact_density()),
                            clonk_name_newlines: definition
                                .clonk_names()
                                .map(|names| names.bytes().filter(|&b| b == b'\n').count() as i32),
                            fire: compat::DefinitionFireMetadata {
                                fire_top: definition.fire_top(),
                                blast_incinerate: definition.blast_incinerate(),
                                burn_turn_to: definition.burn_turn_to().map(str::to_string),
                                incomplete_activity: definition.incomplete_activity(),
                                no_burn_decay: definition.no_burn_decay(),
                                no_burn_damage: definition.no_burn_damage(),
                                contact_incinerate: definition.contact_incinerate(),
                                contain_blast: definition.contain_blast(),
                                no_horizontal_move: definition.no_horizontal_move(),
                                grab: definition.grab(),
                            },
                        },
                    )
                })
                .collect(),
        );
        *cache = Some(Rc::clone(&table));
        table
    }

    fn solid_mask_metadata_table(
        &self,
    ) -> Rc<HashMap<DefinitionId, HostSolidMaskMetadata>> {
        let mut cache = self.solid_mask_metadata_cache.borrow_mut();
        if let Some(table) = cache.as_ref() {
            return Rc::clone(table);
        }
        let table = Rc::new(
            self.definitions
                .iter()
                .map(|(id, definition)| {
                    let image = |image: &DefinitionSpriteImage| {
                        HostSolidMaskImage::new(image.width(), image.height(), image.pixels())
                    };
                    let named_images = definition
                        .sprite_variant_keys()
                        .into_iter()
                        .filter_map(|name| {
                            definition
                                .sprite_image_variant(Some(&name))
                                .map(|sprite| (name.to_ascii_lowercase(), image(sprite)))
                        })
                        .collect();
                    (
                        id.clone(),
                        HostSolidMaskMetadata::new(
                            definition.shape_rect(),
                            definition.solid_mask(),
                            definition.sprite_image().map(image),
                            named_images,
                        ),
                    )
                })
                .collect(),
        );
        *cache = Some(Rc::clone(&table));
        table
    }

    fn host_world_context(&self) -> HostWorldContext {
        let landscape = self.landscape.clone();
        let definition_metadata = self.definition_metadata_table();
        let solid_mask_metadata = self.solid_mask_metadata_table();
        let transfer_zones = self.transfer_zones.states();
        let players: HashMap<i32, PlayerState> = self
            .players
            .values()
            .map(|player| (player.id(), player.to_state()))
            .collect();
        let local_players: Vec<i32> = self
            .local_players
            .as_ref()
            .map_or_else(|| players.keys().copied().collect(), |players| {
                players.iter().copied().collect()
            });
        let crew_selection = self.crew_selection_states();
        let sky_adjustment = self
            .sky
            .as_ref()
            .map(SkyState::adjustment)
            .unwrap_or_default();
        HostWorldContext::with_landscape_shared(
            self.objects.iter().map(|object| {
                let definition = self.definitions.get(&object.definition_id);
                let procedure = definition
                    .and_then(|definition| {
                        definition
                            .action_library()
                            .procedure_name_for_action(&object.state.action.name)
                    })
                    .map(|name| name.to_string());
                // World objects expose the cached mask like C++ obj->OCF
                // (FindObject criteria, host functions).
                let ocf = object.state.ocf;
                HostWorldObject::with_category(
                    object.id,
                    object.definition_id.clone(),
                    object.state.status,
                    object.state.action.name.clone(),
                    object.state.action.target,
                    object.state.action.target2,
                    procedure,
                    object.state.owner,
                    object.state.category,
                    object.state.energy,
                    object.state.construction,
                    object.state.damage,
                    object.state.position,
                    object.state.velocity,
                    object.state.rotation,
                    object.state.vertices.clone(),
                    object.state.action.data,
                    object.state.action.time,
                    object.state.action.phase,
                    object.state.container,
                    object.state.draw_transform,
                )
                .with_fixed_motion(object.fixed_position, object.fixed_velocity)
                .with_move_to_range(definition.map_or(0, Definition::move_to_range))
                .with_pathfinder(definition.map_or(0, Definition::pathfinder))
                .with_no_transfer_zones(definition.map_or(0, Definition::no_transfer_zones))
                .with_contact_density(object.state.contact_density)
                .with_direction(object.state.direction.to_script_value())
                .with_selected(object.state.selected)
                .with_crew_disabled(object.state.crew_disabled)
                .with_contents(object.state.contents.clone())
                .with_alive(object.state.alive)
                .with_need_energy(object.state.need_energy)
                .with_collectible(definition.is_some_and(Definition::is_collectible))
                .with_collection_available_ignoring_delay(definition.is_some_and(|definition| {
                    let mut state = object.state.clone();
                    state.no_collect_delay = 0;
                    definition.compute_ocf(&state) & crate::ocf::COLLECTION != 0
                }))
                .with_collection_limit(definition.and_then(Definition::collection_limit))
                .with_in_liquid(object.state.in_liquid)
                .with_ocf(ocf)
                .with_commands(object.commands.command_views())
                .with_command_stack(object.commands.snapshot())
                .with_full_state(Rc::new(object.state.clone()))
                .with_last_energy_loss_cause(object.last_energy_loss_cause)
            }),
            landscape,
            definition_metadata,
            transfer_zones,
            players,
            crew_selection,
            self.next_object_id,
            self.team_home_base_rule,
        )
        .with_solid_mask_metadata(solid_mask_metadata)
        .with_teams(Rc::clone(&self.teams))
        .with_movement_solid_masks(self.ocf_solid_mask_overlay())
        .with_definition_order(Rc::clone(&self.runtime_definition_order))
        .with_color_by_owner_definitions(
            self.definitions
                .iter()
                .filter(|(_, definition)| definition.color_by_owner())
                .map(|(id, _)| id.clone()),
        )
        // `exec_list` stores C++ Game.Objects reversed for Last -> Prev
        // execution. FindBase is one of the APIs that explicitly walks the
        // forward master list (C4Game.cpp:1582,3732-3744). Inactive objects
        // live only in C4GameObjects::InactiveObjects and never enter this
        // list (C4GameObjects.cpp:54-67).
        .with_master_order(self.exec_list.iter().rev().copied().filter(|&id| {
            self.find_object_index(id)
                .is_some_and(|index| self.objects[index].state.status != ObjectStatus::Inactive)
        }))
        .with_particle_defs(self.particle_system.def_names())
        .with_crew_ranks(Rc::clone(&self.crew_ranks))
        .with_crew_infos(Rc::clone(&self.crew_object_infos))
        .with_materials(Some(self.materials_shared()))
        .with_definition_scripts(
            self.definitions
                .iter()
                .map(|(id, definition)| (id.clone(), definition.script_arc()))
                .collect(),
        )
        .with_definition_descriptions(
            self.definitions
                .iter()
                .filter_map(|(id, definition)| {
                    definition
                        .description()
                        .map(|description| (id.clone(), description.to_string()))
                })
                .collect(),
        )
        .with_scenario_script(
            self.scenario_script
                .as_ref()
                .map(ScenarioScript::script_arc),
        )
        .with_network_game(self.network_game)
        .with_local_players(local_players)
        .with_scoreboard(Rc::clone(&self.scoreboard))
        .with_scenario_script_counter(self.scenario_script_counter)
        .with_command_settings(self.frame, self.base_buy_enabled, self.base_sell_enabled)
        .with_structures_need_energy(self.structures_need_energy)
        .with_crew_name_sources(
            self.standard_names
                .as_ref()
                .map(|names| names.bytes().filter(|&b| b == b'\n').count() as i32)
                .unwrap_or(0),
            self.idle_crew_counts(),
        )
        .with_sky_adjustment(sky_adjustment)
    }

    /// The shared definition-script table host contexts carry (nested
    /// obj->Method resolution; see host_world_context).
    fn definition_script_table(&self) -> HashMap<DefinitionId, Arc<ScriptEngine>> {
        self.definitions
            .iter()
            .map(|(id, definition)| (id.clone(), definition.script_arc()))
            .collect()
    }

    pub fn clear_scenario_script(&mut self) {
        self.scenario_script = None;
    }

    pub fn install_scenario_script(
        &mut self,
        name: impl Into<String>,
        source: &str,
    ) -> Result<Vec<ObjectId>, EngineError> {
        self.install_scenario_script_with_convention(name, source, false)
    }

    /// Like [`install_scenario_script`], with the callback convention:
    /// `c4_args = true` for real (legacy) content — C++ passes no
    /// synthetic state argument and has no fixture Step calls.
    pub fn install_scenario_script_with_convention(
        &mut self,
        name: impl Into<String>,
        source: &str,
        c4_args: bool,
    ) -> Result<Vec<ObjectId>, EngineError> {
        self.load_scenario_script_with_convention(name, source, c4_args)?;
        self.initialize_scenario_script()
    }

    /// Loads and registers a scenario script without calling Initialize.
    /// C++ performs this before loading the scenario-local System.c4g and
    /// linking, while Initialize runs later from InitGame.
    pub fn load_scenario_script_with_convention(
        &mut self,
        name: impl Into<String>,
        source: &str,
        c4_args: bool,
    ) -> Result<(), EngineError> {
        let name = name.into();
        let mut script = ScenarioScript::from_source(name, source)?;
        script.c4_args = c4_args;
        {
            let host = Arc::make_mut(&mut script.script);
            host.set_global_variables(self.script_globals.clone());
            host.set_global_slots(self.script_global_slots.clone());
            host.set_global_constants(self.script_global_consts.clone());
            host.adopt_statics_into_globals();
        }
        let scenario_globals: Vec<(String, lc_script::Function)> = script
            .script
            .global_access_functions()
            .map(|(name, function)| (name.clone(), function.clone()))
            .collect();
        let append_script = script.append_script.clone();
        if let Some(append_script) = append_script {
            self.append_script_sources
                .push(AppendScriptSource::Script(append_script));
        }
        // The scenario script's `global func`s are engine-global like any
        // other script's (C4AulScriptEngine owns AA_GLOBAL functions from
        // EVERY linked script): GoldRush's FxStayThere*/DoInitialize live
        // there and must resolve from def scripts and effect callbacks.
        let mut functions: HashMap<String, lc_script::Function> = self
            .global_script_functions
            .as_deref()
            .cloned()
            .unwrap_or_default();
        let mut changed = false;
        for (name, mut function) in scenario_globals {
            if let Some(previous) = functions.remove(&name) {
                function.push_overload(previous);
            }
            Arc::make_mut(&mut script.script)
                .link_global_access_function(&name, function.clone());
            functions.insert(name, function);
            changed = true;
        }
        if changed {
            let table = Some(Arc::new(functions));
            self.global_script_functions = table.clone();
            for definition in self.definitions.values_mut() {
                definition.set_global_functions(table.clone());
            }
            self.definition_metadata_cache.borrow_mut().take();
            self.solid_mask_metadata_cache.borrow_mut().take();
        }
        script.set_global_functions(self.global_script_functions.clone());
        self.scenario_script = Some(script);
        Ok(())
    }

    /// C4Game::InitGame's per-definition `~InitializeDef` pass. Definitions
    /// run in numeric C4ID order after Objects.txt has been denumerated and
    /// before environment placement (C4Game.cpp:112, 2505-2520). Calls are
    /// fail-safe, but host side effects made before an error still commit.
    pub(crate) fn initialize_definition_scripts(
        &mut self,
    ) -> Result<Vec<ObjectId>, EngineError> {
        let definition_ids = Rc::clone(&self.runtime_definition_order);
        let mut created = Vec::new();
        for definition_id in definition_ids.iter() {
            let Some((script_name, script)) = self
                .definitions
                .get(definition_id)
                .filter(|definition| definition.script.has_function("InitializeDef"))
                .map(|definition| (definition.id.clone(), definition.script_arc()))
            else {
                continue;
            };

            let world = self.host_world_context();
            let (_value, _args, batch, audio_state, rng) =
                ScenarioScript::call_value_for_script(
                    &script_name,
                    &script,
                    Some(definition_id.clone()),
                    "InitializeDef",
                    &[Value::Nil],
                    world,
                    self.rng.clone(),
                    self.frame,
                    &self.global_effects.clone(),
                    self.physics,
                    self.environment,
                    self.audio_registry.clone(),
                    self.game_over_triggered,
                );
            self.rng = rng;
            self.audio_registry = audio_state;
            created.extend(self.apply_scenario_batch(batch)?);
        }
        Ok(created)
    }

    pub fn initialize_scenario_script(&mut self) -> Result<Vec<ObjectId>, EngineError> {
        let Some(c4_args) = self.scenario_script.as_ref().map(|script| script.c4_args) else {
            return Ok(Vec::new());
        };
        let snapshot = self.snapshot();
        let world = self.host_world_context();
        // The `random` Initialize argument is the command-DSL fixture
        // convention — real content (c4_args) burns no synced draw
        // (C++ passes no such argument).
        let random = if c4_args { 0 } else { self.next_random_i32() };
        let rng_state = self.rng.clone();
        let global_effects = self.global_effects.clone();
        let physics = self.physics;
        let environment = self.environment;
        let audio_registry = self.audio_registry.clone();
        let particle_defs = self.particle_system.def_names();
        let definition_scripts = self.definition_script_table();
        let definition_metadata_table = self.definition_metadata_table();
        let definition_order = Rc::clone(&self.runtime_definition_order);
        let network_game = self.network_game;
        let next_object_id = self.next_object_id;
        let scenario_script_counter = self.scenario_script_counter;
        let scoreboard = Rc::clone(&self.scoreboard);
        let materials = self.materials_shared();
        let Some(script) = self.scenario_script.as_mut() else {
            return Ok(Vec::new());
        };
        let (batch, audio_state, new_rng, script_error) = script.initialize(
            &snapshot,
            world,
            scoreboard,
            materials,
            rng_state,
            random,
            &global_effects,
            physics,
            environment,
            audio_registry,
            particle_defs,
            definition_scripts,
            definition_metadata_table,
            definition_order,
            network_game,
            next_object_id,
            scenario_script_counter,
        )?;
        // Initialize is a game call: a script error logs and the scenario
        // still runs WITH its script installed (C++ fail-safe exec,
        // C4AulExec.cpp:1318-1342). Host mutations made before the error
        // already happened and therefore apply before the error is logged.
        self.rng = new_rng;
        self.audio_registry = audio_state;
        let created = self.apply_scenario_batch(batch)?;
        if let Some(error) = script_error {
            tolerate_script_error::<()>(Err(error))?;
        }
        self.game_over_triggered = false;
        self.game_evaluated = false;
        Ok(created)
    }

    fn broadcast_scenario_function(
        &mut self,
        function: &str,
        extra_args: Vec<Value>,
    ) -> Result<(), EngineError> {
        // C4GameScriptHost::GRBroadcast (C4ScriptHost.cpp:234-249): every
        // live object with a C4D_Goal|C4D_Rule|C4D_Environment category bit
        // is called FIRST ("call objects first - scenario script might
        // overwrite hostility, etc."), results discarded; the scenario
        // script runs after. Object-call errors log-and-continue
        // (fPassError defaults false).
        const BROADCAST_MASK: i32 = (1 << 5) | (1 << 6) | (1 << 19);
        let broadcast_targets: Vec<usize> = self
            .objects
            .iter()
            .enumerate()
            .filter(|(_, object)| {
                !object.destroyed
                    && object.state.status.is_active()
                    && object.state.category & BROADCAST_MASK != 0
            })
            .map(|(index, _)| index)
            .collect();
        for index in broadcast_targets {
            // The C++ loop re-checks Status against the live list — an
            // earlier broadcast call may have removed the object.
            if self.objects[index].destroyed || !self.objects[index].state.status.is_active() {
                continue;
            }
            let definition_id = self.objects[index].definition_id.clone();
            // A missing function is no error (GetSFunc miss → C4Value()).
            let has_function = self
                .definitions
                .get(&definition_id)
                .map(|definition| definition.has_function(function))
                .unwrap_or(false);
            if !has_function {
                continue;
            }
            if let Err(error) = self.call_object_function(index, function, extra_args.clone()) {
                tracing::warn!(
                    definition = %definition_id,
                    function,
                    %error,
                    "script error in engine callback; continuing like the C++ fail-safe exec"
                );
            }
        }

        self.call_scenario_script_function(function, extra_args)
    }

    /// Runs a function on the SCENARIO SCRIPT ONLY (Game.Script.Call) —
    /// the direct-call half of GRBroadcast, also used by the Script%d
    /// counter sections (C4GameScriptHost::Execute, C4ScriptHost.cpp:
    /// 222-232).
    #[doc(hidden)]
    pub fn call_scenario_script_function(
        &mut self,
        function: &str,
        mut extra_args: Vec<Value>,
    ) -> Result<(), EngineError> {
        if self.scenario_script.is_none() {
            return Ok(());
        }
        let snapshot = self.snapshot();
        let world = self.host_world_context();
        let c4_args = self
            .scenario_script
            .as_ref()
            .map(|script| script.c4_args)
            .unwrap_or(false);
        let mut args = Vec::with_capacity(extra_args.len() + 1);
        // GRBroadcast passes the C++ argument list as-is (e.g.
        // PSF_InitializePlayer starts with the player number,
        // C4Player.cpp:769-775); the state proplist is fixture-only.
        if !c4_args {
            args.push(build_scenario_state_value(&snapshot));
        }
        args.append(&mut extra_args);
        let rng_state = self.rng.clone();
        let env_frame = self.frame;
        let global_effects = self.global_effects.clone();
        let physics = self.physics;
        let environment = self.environment;
        let audio_state = self.audio_registry.clone();
        let particle_defs = self.particle_system.def_names();
        let definition_scripts = self.definition_script_table();
        let definition_metadata_for_call = self.definition_metadata_table();
        let definition_order = Rc::clone(&self.runtime_definition_order);
        let network_game = self.network_game;
        let engine_next_object_id = self.next_object_id;
        let scenario_script_counter = self.scenario_script_counter;
        let scoreboard = Rc::clone(&self.scoreboard);
        let materials = self.materials_shared();
        let script = match self.scenario_script.as_mut() {
            Some(script) if script.has_function(function) => script,
            Some(_) => return Ok(()),
            None => unreachable!("scenario script must be present"),
        };
        let (batch, audio_state, new_rng, script_error) = script.call_raw(
            function,
            args,
            &snapshot,
            world,
            scoreboard,
            materials,
            rng_state,
            env_frame,
            &global_effects,
            physics,
            environment,
            audio_state,
            particle_defs,
            definition_scripts,
            definition_metadata_for_call,
            definition_order,
            network_game,
            engine_next_object_id,
            scenario_script_counter,
        )?;
        self.rng = new_rng;
        self.audio_registry = audio_state;
        // Partial side effects fold BEFORE the error surfaces: C++
        // mutates live state as the script runs — GoldRush's Script1
        // creates the intro Talker before any later line can fail.
        let _ = self.apply_scenario_batch(batch)?;
        match script_error {
            Some(error) => Err(error),
            None => Ok(()),
        }
    }

    fn check_game_over(&mut self) -> Result<(), EngineError> {
        if self.game_over_triggered || !self.players_registered {
            return Ok(());
        }

        let mut should_trigger = !self.has_active_players();

        if !should_trigger && self.should_evaluate_objectives() && self.objectives_met() {
            should_trigger = true;
        }

        if should_trigger {
            self.request_game_over()?;
        }

        Ok(())
    }

    fn has_active_players(&self) -> bool {
        self.players
            .values()
            .any(|player| {
                !matches!(
                    player.status(),
                    PlayerStatus::Eliminated | PlayerStatus::Surrendered
                ) && !player.surrendered()
            })
    }

    fn should_evaluate_objectives(&self) -> bool {
        !self.objectives.is_empty() && self.objective_check_counter == 0
    }

    fn objectives_met(&self) -> bool {
        if self.objectives.is_empty() {
            return false;
        }

        let mut game_over_valid = false;
        let mut game_over = true;

        if !self.objectives.create_objects.is_empty() {
            let mut condition_valid = false;
            let mut condition_true = true;
            for objective in &self.objectives.create_objects {
                if objective.count <= 0 {
                    continue;
                }
                condition_valid = true;
                let target_id = objective.definition.as_str();
                let current = self
                    .objects
                    .iter()
                    .filter(|object| object.definition_id.as_str() == target_id)
                    .filter(|object| object.state.status.is_active())
                    .filter(|object| object.state.construction >= FULL_CON)
                    .count() as i32;
                if current < objective.count {
                    condition_true = false;
                }
            }
            if condition_valid {
                game_over_valid = true;
                if !condition_true {
                    game_over = false;
                }
            }
        }

        if !self.objectives.clear_objects.is_empty() {
            let mut condition_valid = false;
            let mut condition_true = true;
            for objective in &self.objectives.clear_objects {
                condition_valid = true;
                let limit = objective.count.max(0);
                let target_id = objective.definition.as_str();
                let alive_only = self
                    .definitions
                    .get(target_id)
                    .map(|definition| definition.category() & CATEGORY_LIVING != 0)
                    .unwrap_or(false);
                let count = self
                    .objects
                    .iter()
                    .filter(|object| object.definition_id.as_str() == target_id)
                    .filter(|object| object.state.status.is_active())
                    .filter(|object| !alive_only || object.state.alive)
                    .count() as i32;
                if count > limit {
                    condition_true = false;
                }
            }
            if condition_valid {
                game_over_valid = true;
                if !condition_true {
                    game_over = false;
                }
            }
        }

        if !self.objectives.clear_materials.is_empty() {
            let mut condition_valid = false;
            let mut condition_true = true;
            if let Some(landscape) = self.landscape.as_ref() {
                for objective in &self.objectives.clear_materials {
                    if let Some(material_id) = self.materials.id_of(&objective.material) {
                        condition_valid = true;
                        let limit = i64::from(objective.count.max(0));
                        let total = self.count_material_pixels(landscape, material_id);
                        if total > limit {
                            condition_true = false;
                        }
                    }
                }
            }
            if condition_valid {
                game_over_valid = true;
                if !condition_true {
                    game_over = false;
                }
            }
        }

        game_over_valid && game_over
    }

    fn count_material_pixels(&self, landscape: &Landscape, material_id: MaterialId) -> i64 {
        let mut total: i64 = 0;

        for x in 0..landscape.width() {
            if landscape.solid_material_at(x as i32) == Some(material_id) {
                let height = landscape
                    .surface()
                    .get(x as usize)
                    .copied()
                    .unwrap_or_default()
                    .max(0);
                total += i64::from(height);
            }
        }

        for column in landscape.liquids() {
            for segment in column.segments() {
                if segment.material == Some(material_id) {
                    let span = i64::from(segment.bottom) - i64::from(segment.top);
                    if span > 0 {
                        total += span;
                    }
                }
            }
        }

        total
    }

    fn request_game_over(&mut self) -> Result<bool, EngineError> {
        if self.game_over_triggered {
            return Ok(false);
        }
        self.game_over_triggered = true;
        tolerate_script_error(self.broadcast_scenario_function("OnGameOver", Vec::new()))?;
        // C4Game::DoGameOver marks winners only after OnGameOver, so any
        // player eliminated by that callback is not promoted (C4Game.cpp:
        // 3659-3670).
        for player in self.players.values_mut() {
            if !matches!(
                player.status(),
                PlayerStatus::Eliminated | PlayerStatus::Surrendered
            ) && !player.surrendered()
            {
                player.mark_won();
            }
        }
        Ok(true)
    }

    fn evaluate_game(&mut self) -> Result<(), EngineError> {
        if self.game_evaluated {
            return Ok(());
        }

        // Cooperative games award every player the average of all positive
        // ValueGain values (C4PlayerList::AverageValueGain). A melee flag is
        // not modeled yet, so do not infer one from goals or player count.
        let average_value_gain = if self.players.is_empty() {
            0
        } else {
            let sum = self.players.values().fold(0_i32, |sum, player| {
                sum.wrapping_add(player.value_gain().max(0))
            });
            sum / i32::try_from(self.players.len()).unwrap_or(i32::MAX)
        };

        let mut player_numbers: Vec<_> = self.players.keys().copied().collect();
        player_numbers.sort_unstable();
        for number in player_numbers {
            let evaluated = {
                let player = self
                    .players
                    .get_mut(&number)
                    .ok_or(EngineError::UnknownPlayer(number))?;
                player
                    .evaluate(average_value_gain, self.game_time)
                    .map(|(score_old, score_new)| {
                        (
                            player.player_info_id(),
                            player.total_playing_time() as u32,
                            score_old,
                            score_new,
                        )
                    })
            };
            let Some((player_info_id, total_playing_time, score_old, score_new)) = evaluated else {
                continue;
            };
            if let Some(result) = self
                .round_results
                .players
                .iter_mut()
                .find(|result| result.player_info_id == player_info_id)
            {
                result.total_playing_time = total_playing_time;
                result.score_old = score_old;
                result.score_new = Some(score_new);
            } else {
                self.round_results.players.push(RoundResultsPlayerState {
                    player_info_id,
                    total_playing_time,
                    score_old,
                    score_new: Some(score_new),
                    custom_evaluation_strings: String::new(),
                });
            }
        }

        let (goals, fulfilled_goals) = self.evaluate_round_goals()?;
        self.round_results.goals = goals;
        self.round_results.fulfilled_goals = fulfilled_goals;
        // C4RoundResults::EvaluateGame writes playing time after all goal
        // callbacks, whose scripts may mutate Game.Time.
        self.round_results.playing_time_seconds = self.game_time as u32;
        self.game_evaluated = true;
        Ok(())
    }

    #[doc(hidden)]
    pub fn evaluate_round_goals(
        &mut self,
    ) -> Result<(Vec<DefinitionId>, Vec<DefinitionId>), EngineError> {
        let rivalry = self
            .exec_list
            .iter()
            .rev()
            .any(|&object_id| {
                let Some(index) = self.find_object_index(object_id) else {
                    return false;
                };
                let object = &self.objects[index];
                !object.destroyed
                    && object.state.status.is_active()
                    && object.definition_id.as_str() == "RVLR"
            });
        let first_local_player = self
            .players
            .keys()
            .copied()
            .filter(|player| {
                self.local_players
                    .as_ref()
                    .is_none_or(|local| local.contains(player))
            })
            .min()
            .unwrap_or(OWNER_NONE);

        let mut goals = Vec::new();
        let mut fulfilled = Vec::new();
        // C4ObjectList::GetListID uses a 500-entry temporary ID table.
        for goal_index in 0..500 {
            // GetListID rebuilds its unique-ID list on every call. Goal
            // callbacks can remove objects, so the cnt-th ID must be found
            // again from the current master list (C4ObjectList.cpp:58-78).
            let goal = {
                let mut seen = HashSet::new();
                self.exec_list
                    .iter()
                    .rev()
                    .filter_map(|&object_id| {
                        let index = self.find_object_index(object_id)?;
                        let object = &self.objects[index];
                        if object.destroyed || !object.state.status.is_active() {
                            return None;
                        }
                        let definition = self.definitions.get(&object.definition_id)?;
                        (definition.category() & CATEGORY_GOAL != 0
                            && seen.insert(object.definition_id.clone()))
                        .then(|| object.definition_id.clone())
                    })
                    .nth(goal_index)
            };
            let Some(goal) = goal else {
                break;
            };

            // C4ObjectList::Find re-resolves the first live instance for
            // every distinct goal ID; an earlier callback may have removed
            // the instance that originally contributed the ID.
            let target = self.exec_list.iter().rev().find_map(|&object_id| {
                let index = self.find_object_index(object_id)?;
                let object = &self.objects[index];
                (!object.destroyed
                    && object.state.status.is_active()
                    && object.definition_id == goal)
                    .then_some(index)
            });
            let is_fulfilled = if let Some(index) = target {
                let (function, args) = if rivalry {
                    (
                        "IsFulfilledforPlr",
                        vec![Value::Int(first_local_player)],
                    )
                } else {
                    ("IsFulfilled", Vec::new())
                };
                tolerate_script_error(self.call_object_function(index, function, args))?
                    .is_some_and(|value| compat::value_raw_truthy(&value))
            } else {
                false
            };
            goals.push(goal.clone());
            if is_fulfilled {
                fulfilled.push(goal);
            }
        }
        Ok((goals, fulfilled))
    }

    pub fn next_mission(&self) -> &NextMissionState {
        &self.next_mission
    }

    fn apply_next_mission_commands(
        &mut self,
        commands: impl IntoIterator<Item = NextMissionCommand>,
    ) {
        for command in commands {
            match command {
                NextMissionCommand::Set {
                    path,
                    text,
                    description,
                } => {
                    self.next_mission = NextMissionState {
                        path,
                        text,
                        description,
                    };
                }
                NextMissionCommand::Clear => {
                    self.next_mission.path.clear();
                    self.next_mission.text.clear();
                    // FnSetNextMission deliberately leaves NextMissionDesc
                    // untouched when clearing (C4Script.cpp:6055-6061).
                }
            }
        }
    }

    #[doc(hidden)]
    pub fn apply_scenario_batch(&mut self, batch: ScenarioBatch) -> Result<Vec<ObjectId>, EngineError> {
        let ScenarioBatch {
            spawns,
            other_objects,
            global_effects,
            environment,
            physics,
            landscape_ops,
            landscape,
            particles,
            transfer_zones,
            audio,
            messages,
            player_commands,
            object_order_commands,
            next_mission_commands,
            trigger_game_over,
            script_go,
            script_counter,
        } = batch;

        if !player_commands.is_empty() {
            self.apply_player_commands(player_commands)?;
        }
        self.pending_object_order_commands.extend(object_order_commands);
        self.apply_next_mission_commands(next_mission_commands);

        if !landscape_ops.is_empty() {
            self.apply_landscape_operations(landscape_ops);
        }

        if let Some(delta) = environment {
            self.apply_environment_delta(&delta);
        }
        if let Some(delta) = physics {
            self.apply_physics_delta(delta);
        }
        if !global_effects.is_empty() {
            self.apply_global_effect_commands(&global_effects);
        }
        if !landscape.is_empty() {
            let mut landscape_slot = self.landscape.take();
            if let Some(landscape_ref) = landscape_slot.as_mut() {
                for command in landscape {
                    command.apply(landscape_ref);
                }
            }
            self.landscape = landscape_slot;
            // C++ landscape drawing never touches the mass-mover set —
            // movers pinned to changed pixels die on their next Execute
            // (C4MassMover.cpp:119).
        }
        self.apply_particle_commands(particles);
        if !audio.is_empty() {
            self.pending_audio.extend(audio);
        }
        if !messages.is_empty() {
            for command in messages {
                self.messages.apply_command(command);
            }
        }

        // Pre-scan spawns to find maximum explicit ID and reserve ID space
        // This prevents conflicts between auto-assigned IDs (from earlier objects like crew)
        // and explicit IDs (from scenario Objects.txt)
        let max_explicit_id = spawns
            .iter()
            .filter_map(|spawn| spawn.id)
            .map(|id| id.as_u64())
            .max();

        if let Some(max_id) = max_explicit_id {
            // Reserve ID space: ensure next_object_id is beyond all explicit IDs
            if max_id >= self.next_object_id {
                self.next_object_id = max_id + 1;
            }
        }

        let mut created = Vec::with_capacity(spawns.len());
        for spawn in spawns {
            match self.spawn_object(spawn) {
                Ok(id) => created.push(id),
                // CreateObject resolves the id with C4Id2Def and yields
                // nullptr for unknown definitions — never an error
                // (Drachenfels' Initialize creates `_EAI` before its def
                // loads). Mirrors the process_spawn_queue tolerance.
                Err(EngineError::UnknownDefinition(definition)) => {
                    tracing::warn!(%definition, "scenario spawn names an unknown definition; skipped");
                }
                Err(error) => return Err(error),
            }
        }
        // Transfer zones fold AFTER the spawns: C4Game::NewObject adds the
        // object to Game.Objects BEFORE its creation callbacks fire
        // (C4Game.cpp:1115-1131), so a SetTransferZone recorded during the
        // scenario Initialize (C4Script.cpp:3145-3149) always found its
        // owner live — including owners this very batch creates.
        if !transfer_zones.is_empty() {
            self.apply_transfer_zone_commands(transfer_zones)?;
        }
        // Nested-call outcomes fold AFTER the spawns: scripts arrow-call
        // objects they just created (C++ creates them live mid-call), so
        // outcomes may target this batch's fresh ids.
        self.apply_nested_object_outcomes(other_objects)?;
        if let Some(go) = script_go {
            self.scenario_script_go = go;
        }
        if let Some(counter) = script_counter {
            self.scenario_script_counter = counter;
        }
        if trigger_game_over {
            self.request_game_over()?;
        }
        Ok(created)
    }

    pub fn crew_members(&self, owner: i32) -> Vec<ObjectId> {
        self.objects
            .iter()
            .filter(|object| {
                object.state.crew_member
                    && object.state.owner == owner
                    && object.state.status.is_active()
            })
            .map(|object| object.id)
            .collect()
    }

    pub fn eliminated_owners(&self) -> Vec<i32> {
        let mut eliminated: Vec<_> = self.eliminated_crew_owners.iter().cloned().collect();
        eliminated.sort_unstable();
        eliminated
    }

    pub fn is_owner_eliminated(&self, owner: i32) -> bool {
        self.eliminated_crew_owners.contains(&owner)
    }

    pub fn selected_crew(&self, owner: i32) -> Vec<ObjectId> {
        // GetCursor(index) scans C4Player::Crew in its stored list order
        // (C4Script.cpp:2905-2928). Object numbers are not an ordering key:
        // loaded games may assign arbitrary ids, so follow the player's
        // actual roster and only fall back to object insertion order in the
        // playerless engine fixtures.
        let roster = self
            .players
            .get(&owner)
            .map(|player| player.crew().to_vec())
            .unwrap_or_else(|| self.crew_members(owner));
        roster
            .into_iter()
            .filter(|id| {
                self.find_object_index(*id)
                    .is_some_and(|index| self.objects[index].state.selected)
            })
            .collect()
    }

    fn crew_selection_state(&self, owner: i32) -> CrewSelectionState {
        CrewSelectionState {
            selected: self.selected_crew(owner),
            cursor: self.crew_cursor(owner),
        }
    }

    fn crew_selection_states(&self) -> HashMap<i32, CrewSelectionState> {
        let mut owners: HashSet<i32> = self.crew_selection.keys().copied().collect();
        owners.extend(
            self.objects
                .iter()
                .filter(|object| object.state.selected)
                .map(|object| object.state.owner),
        );
        owners
            .into_iter()
            .filter_map(|owner| {
                let state = self.crew_selection_state(owner);
                (!state.selected.is_empty() || state.cursor.is_some()).then_some((owner, state))
            })
            .collect()
    }

    pub fn crew_cursor(&self, owner: i32) -> Option<ObjectId> {
        self.crew_selection
            .get(&owner)
            .and_then(|selection| selection.cursor())
    }

    pub fn select_crew<I>(&mut self, owner: i32, crew: I) -> Result<(), EngineError>
    where
        I: IntoIterator<Item = ObjectId>,
    {
        let mut validated = Vec::new();
        for id in crew {
            let object = self
                .objects
                .iter()
                .find(|object| object.id == id)
                .ok_or(EngineError::UnknownObject(id))?;
            if object.state.owner != owner {
                return Err(EngineError::CrewSelection {
                    owner,
                    detail: format!("object {} is owned by {}", id, object.state.owner),
                });
            }
            if !object.state.crew_member {
                return Err(EngineError::CrewSelection {
                    owner,
                    detail: format!("object {} is not a crew member", id),
                });
            }
            if !object.state.status.is_active() {
                return Err(EngineError::CrewSelection {
                    owner,
                    detail: format!("object {} is not active", id),
                });
            }
            validated.push(id);
        }

        if validated.is_empty() {
            return Ok(());
        }

        for id in validated {
            if let Some(index) = self.find_object_index(id) {
                self.object_do_select(index, owner, false)?;
            }
        }
        // Crew selection flashes the select marks (C4Player::SelectCrew,
        // C4Player.cpp:1846 / SelectSingleByCursor, :1317).
        if let Some(player) = self.players.get_mut(&owner) {
            player.control.select_flash = 30;
            player.control.cursor_selection = 0;
            player.control.cursor_toggled = 0;
        }
        self.player_adjust_cursor_command(owner)?;
        Ok(())
    }

    pub fn deselect_crew<I>(&mut self, owner: i32, crew: I)
    where
        I: IntoIterator<Item = ObjectId>,
    {
        for id in crew {
            if let Some(index) = self.find_object_index(id) {
                if self.objects[index].state.owner == owner
                    && self.objects[index].state.crew_member
                {
                    let _ = self.object_un_select(index, owner, false);
                }
            }
        }
        if let Some(player) = self.players.get_mut(&owner) {
            player.control.select_flash = 30;
            player.control.cursor_selection = 0;
            player.control.cursor_toggled = 0;
        }
        let _ = self.player_adjust_cursor_command(owner);
    }

    pub fn clear_crew_selection(&mut self, owner: i32) {
        let _ = self.player_unselect_crew(owner);
        self.crew_selection.remove(&owner);
        self.sync_player_cursor(owner);
    }

    pub fn set_crew_cursor(
        &mut self,
        owner: i32,
        cursor: Option<ObjectId>,
    ) -> Result<(), EngineError> {
        match cursor {
            Some(id) => {
                let object = self
                    .objects
                    .iter()
                    .find(|object| object.id == id)
                    .ok_or(EngineError::UnknownObject(id))?;
                if object.state.owner != owner {
                    return Err(EngineError::CrewSelection {
                        owner,
                        detail: format!("object {} is owned by {}", id, object.state.owner),
                    });
                }
                if !object.state.crew_member {
                    return Err(EngineError::CrewSelection {
                        owner,
                        detail: format!("object {} is not a crew member", id),
                    });
                }
                if !object.state.status.is_active() {
                    return Err(EngineError::CrewSelection {
                        owner,
                        detail: format!("object {} is not active", id),
                    });
                }
                self.player_set_cursor(owner, Some(id), false, true)?;
            }
            None => {
                self.player_set_cursor(owner, None, false, true)?;
            }
        }

        self.sync_player_cursor(owner);
        Ok(())
    }

    pub fn ensure_cursor(&mut self, owner: i32) -> Result<(), EngineError> {
        if self.crew_cursor(owner).is_some() {
            return Ok(());
        }
        self.player_adjust_cursor_command(owner)
    }

    pub fn context_menu_entries(
        &mut self,
        object_id: ObjectId,
    ) -> Result<Vec<ContextMenuEntry>, EngineError> {
        let index = self
            .objects
            .iter()
            .position(|object| object.id == object_id)
            .ok_or(EngineError::UnknownObject(object_id))?;
        let definition_id = self.objects[index].definition_id.clone();
        let state_snapshot = self.objects[index].script_state_snapshot();
        let definition = self
            .definitions
            .get(&definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
        // C4ObjectMenu::AddContextFunctions enumerates effective annotated
        // Context* functions separately from the Rust-port MenuEntries hook
        // (C4ObjectMenu.cpp:398-399,670-682). Keep a detached copy so their
        // conditions can run through the live engine after MenuEntries releases
        // the immutable definition borrow.
        let legacy_context_functions = definition.script_context_functions();
        let definitions_ref = &self.definitions;
        let rng_state = self.rng.clone();
        let global_view = self.global_effects.clone();
        let world = self.host_world_context();
        let (mut entries, audio_state, new_rng) = definition.call_menu_entries(
            &state_snapshot,
            object_id,
            rng_state,
            &global_view,
            self.physics,
            self.environment,
            self.frame,
            world,
            self.game_over_triggered,
            self.audio_registry.clone(),
        )?;
        self.rng = new_rng;
        self.audio_registry = audio_state;

        // C++ calls each Condition on the context target with the menu object
        // and annotation image id. The player-facing menu is built for its
        // cursor, so the target and menu object are this same crew object.
        for context in legacy_context_functions {
            let image = context.image.as_deref().unwrap_or("NONE");
            let enabled = match context.condition.as_deref() {
                Some(condition) => {
                    let value = self.call_object_function(
                        index,
                        condition,
                        vec![
                            compat::object_reference_value(object_id),
                            Value::C4Id(image.to_owned()),
                        ],
                    )?;
                    compat::value_raw_truthy(&value)
                }
                None => true,
            };
            if enabled {
                entries.push(ContextMenuEntry {
                    function: context.function,
                    label: context.label,
                    description: context.description,
                });
            }
        }
        Ok(entries)
    }

    pub fn menu_command(
        &mut self,
        crew_id: ObjectId,
        kind: MenuCommandKind,
        selection: MenuCommandSelection,
    ) -> Result<bool, EngineError> {
        let index = self
            .objects
            .iter()
            .position(|object| object.id == crew_id)
            .ok_or(EngineError::UnknownObject(crew_id))?;
        let definition_id = self.objects[index].definition_id.clone();
        let state_snapshot = self.objects[index].script_state_snapshot();
        let definition = self
            .definitions
            .get(&definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
        let definitions_ref = &self.definitions;
        let action_library = definition.action_library().clone();
        let rng_state = self.rng.clone();
        let global_view = self.global_effects.clone();
        let world = self.host_world_context();
        let (handled, outcome, audio_state, new_rng) = definition.call_menu_command(
            &state_snapshot,
            crew_id,
            kind,
            &selection,
            rng_state,
            &global_view,
            self.physics,
            self.environment,
            self.frame,
            world,
            self.game_over_triggered,
            self.audio_registry.clone(),
        )?;
        self.rng = new_rng;
        self.audio_registry = audio_state;
        self.apply_action_callback_outcome(
            index,
            outcome,
            &action_library,
            crew_id,
            &definition_id,
        )?;
        Ok(handled)
    }

    pub fn execute_context_menu(
        &mut self,
        object_id: ObjectId,
        function: &str,
    ) -> Result<bool, EngineError> {
        let index = self
            .objects
            .iter()
            .position(|object| object.id == object_id)
            .ok_or(EngineError::UnknownObject(object_id))?;
        let definition_id = self.objects[index].definition_id.clone();
        let state_snapshot = self.objects[index].script_state_snapshot();
        let definition = self
            .definitions
            .get(&definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
        let is_legacy_context = definition
            .script_context_functions()
            .iter()
            .any(|context| context.function == function);
        if is_legacy_context {
            // C4ObjectMenu installs
            // ProtectedCall(target, "Context*", menu_object): the selected
            // legacy function receives a live object reference, not the state
            // proplist used by the Rust-port MenuEntries callback convention
            // (C4ObjectMenu.cpp:650-665,678-680).
            let value = self.call_object_function(
                index,
                function,
                vec![compat::object_reference_value(object_id)],
            )?;
            return Ok(compat::value_raw_truthy(&value));
        }
        let definitions_ref = &self.definitions;
        let action_library = definition.action_library().clone();
        let rng_state = self.rng.clone();
        let global_view = self.global_effects.clone();
        let world = self.host_world_context();
        let (handled, outcome, audio_state, new_rng) = definition.call_menu_callback(
            &state_snapshot,
            object_id,
            function,
            rng_state,
            &global_view,
            self.physics,
            self.environment,
            self.frame,
            world,
            self.game_over_triggered,
            self.audio_registry.clone(),
        )?;
        self.rng = new_rng;
        self.audio_registry = audio_state;
        self.apply_action_callback_outcome(
            index,
            outcome,
            &action_library,
            object_id,
            &definition_id,
        )?;
        Ok(handled)
    }

    #[doc(hidden)]
    pub fn call_object_function(
        &mut self,
        index: usize,
        function: &str,
        args: Vec<Value>,
    ) -> Result<Value, EngineError> {
        let (object_id, definition_id, state_snapshot) = {
            let object = self
                .objects
                .get(index)
                .ok_or_else(|| EngineError::UnknownObject(ObjectId::new(u64::MAX)))?;
            (
                object.id,
                object.definition_id.clone(),
                object.script_state_snapshot(),
            )
        };
        let definition = self
            .definitions
            .get(&definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
        let definitions_ref = &self.definitions;
        let action_library = definition.action_library().clone();
        let rng_state = self.rng.clone();
        let global_view = self.global_effects.clone();
        let world = self.host_world_context();
        let call = definition.call_object_function(
            &state_snapshot,
            object_id,
            function,
            &args,
            rng_state,
            &global_view,
            self.physics,
            self.environment,
            self.frame,
            world,
            self.game_over_triggered,
            self.audio_registry.clone(),
        );
        let (value, outcome, audio_state, new_rng) = match call {
            Ok(ok) => ok,
            // Pre-error mutations persist (C++ mutated the live objects).
            Err(error) => {
                return Err(self.apply_script_error_recovery(
                    error,
                    index,
                    &action_library,
                    object_id,
                    &definition_id,
                    true,
                ));
            }
        };
        self.rng = new_rng;
        self.audio_registry = audio_state;
        self.apply_action_callback_outcome(
            index,
            outcome,
            &action_library,
            object_id,
            &definition_id,
        )?;
        Ok(value)
    }

    /// C4Object::MenuCommand (C4Object.cpp:3756-3760): DirectExec `source`
    /// in the object's own script context and fold the outcome like any
    /// object call. Error handling (fPassErrors=false — log and continue)
    /// is the caller's via `tolerate_script_error`.
    fn direct_exec_on_object(
        &mut self,
        index: usize,
        source: &str,
        label: &str,
    ) -> Result<Value, EngineError> {
        let (object_id, definition_id, state_snapshot) = {
            let object = self
                .objects
                .get(index)
                .ok_or_else(|| EngineError::UnknownObject(ObjectId::new(u64::MAX)))?;
            (
                object.id,
                object.definition_id.clone(),
                object.script_state_snapshot(),
            )
        };
        let definition = self
            .definitions
            .get(&definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
        let action_library = definition.action_library().clone();
        let rng_state = self.rng.clone();
        let global_view = self.global_effects.clone();
        let world = self.host_world_context();
        let call = definition.direct_exec_object_expression(
            &state_snapshot,
            object_id,
            source,
            label,
            rng_state,
            &global_view,
            self.physics,
            self.environment,
            self.frame,
            world,
            self.game_over_triggered,
            self.audio_registry.clone(),
        );
        let (value, outcome, audio_state, new_rng) = match call {
            Ok(ok) => ok,
            // Pre-error mutations persist (C++ mutated the live objects).
            Err(error) => {
                return Err(self.apply_script_error_recovery(
                    error,
                    index,
                    &action_library,
                    object_id,
                    &definition_id,
                    true,
                ));
            }
        };
        self.rng = new_rng;
        self.audio_registry = audio_state;
        self.apply_action_callback_outcome(
            index,
            outcome,
            &action_library,
            object_id,
            &definition_id,
        )?;
        Ok(value)
    }

    /// The sim-observable core of a user Enter on the object's SCRIPT menu
    /// — C4Menu::Enter (C4Menu.cpp:498-523), reached in C++ via the queued
    /// COM_MenuEnter/COM_MenuEnterAll control (C4ObjectMenu::OnUserEnter,
    /// C4ObjectMenu.cpp:467-471; C4Object::Control -> Menu->Control,
    /// C4Object.cpp:3365-3367): the selected item's command string executes
    /// on the menu's command object (C4ObjectMenu::MenuCommand ->
    /// C4Object::MenuCommand DirectExec, C4ObjectMenu.cpp:505-527 /
    /// C4Object.cpp:3756-3760). The app-side menu UI must route its Enter
    /// here; see the PORT_STATUS `object menus` row for what remains.
    pub fn menu_user_enter(
        &mut self,
        object_id: ObjectId,
        right: bool,
    ) -> Result<bool, EngineError> {
        const STYLE_INFO: i32 = 2; // C4MN_Style_Info (C4Menu.h:41)
        const STYLE_DIALOG: i32 = 3; // C4MN_Style_Dialog (C4Menu.h:42)
        let Some(index) = self.find_object_index(object_id) else {
            return Ok(false);
        };
        let Some(menu) = self.objects[index].state.menu.clone() else {
            return Ok(false); // !IsActive (C4Menu.cpp:501)
        };
        if menu.style == STYLE_INFO {
            return Ok(false); // C4Menu.cpp:502
        }
        let item = usize::try_from(menu.selection)
            .ok()
            .and_then(|selection| menu.items.get(selection));
        let Some(item) = item else {
            // No selected item: dialogs try a soft close (TryClose(false,
            // true), C4Menu.cpp:508); every style reports true (:509).
            if menu.style == STYLE_DIALOG {
                self.close_object_menu(object_id, false)?;
            }
            return Ok(true);
        };
        // Copy the command to a buffer (the menu may clear); right enter
        // takes Command2 when set (C4Menu.cpp:512-514).
        let command = if right && !item.command2.is_empty() {
            item.command2.clone()
        } else {
            item.command.clone()
        };
        // Close if not permanent BEFORE the exec — Close(true) skips the
        // MenuQueryCancel query (C4Menu.cpp:517).
        if !menu.permanent {
            self.objects[index].state.menu = None;
        }
        // C4ObjectMenu::MenuCommand CB_Object (C4ObjectMenu.cpp:519-521):
        // DirectExec on the command object, fail-safe (fPassErrors=false).
        // CB_Scenario (Game.Script.DirectExec, :523-526) is unported —
        // see PORT_STATUS. C4Player::Execute performs the later
        // AutoContextMenu pass through execute_player_controls.
        match menu.command_object.and_then(|id| self.find_object_index(id)) {
            Some(command_index) => {
                tolerate_script_error(self.direct_exec_on_object(
                    command_index,
                    &command,
                    "MenuCommand",
                ))?;
            }
            None => {
                tracing::warn!(
                    id = object_id.as_u64(),
                    command,
                    "menu Enter without a command object (CB_Scenario MenuCommand unported)"
                );
            }
        }
        // Internal permanent inventory/base menus are refill-driven. The
        // selected command may have changed stock or contents
        // synchronously, so rebuild immediately like C4ObjectMenu::Execute
        // (C4ObjectMenu.cpp:124-129, 207-326, 450-459).
        if !menu.user_menu
            && menu.permanent
            && matches!(
                &menu.identification,
                Value::Int(4) | Value::Int(5) | Value::Int(17) | Value::Int(18)
            )
        {
            let indices = self
                .find_object_index(object_id)
                .and_then(|crew_index| {
                    self.objects[crew_index]
                        .state
                        .container
                        .and_then(|base_id| self.find_object_index(base_id))
                        .map(|base_index| (crew_index, base_index))
                });
            if let Some((crew_index, base_index)) = indices {
                match menu.identification {
                    Value::Int(4) => self.open_base_buy_menu(crew_index, base_index)?,
                    Value::Int(5) => self.open_base_sell_menu(crew_index, base_index)?,
                    Value::Int(17) => {
                        self.open_container_contents_menu(crew_index, base_index, 17)?;
                    }
                    Value::Int(18) => {
                        self.open_container_contents_menu(crew_index, base_index, 18)?;
                    }
                    _ => {}
                }
            }
        }
        Ok(true)
    }

    fn call_movement_object_function(
        &mut self,
        index: usize,
        function: &str,
        args: &[Value],
        action_library: &ActionLibrary,
        object_id: ObjectId,
        definition_id: &str,
    ) -> Result<Value, EngineError> {
        let state_snapshot = self
            .objects
            .get(index)
            .ok_or_else(|| EngineError::UnknownObject(ObjectId::new(u64::MAX)))?
            .state
            .clone();
        let definition = self
            .definitions
            .get(definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.to_string()))?;
        let definitions_ref = &self.definitions;
        let rng_state = self.rng.clone();
        let global_view = self.global_effects.clone();
        let world = self.host_world_context();
        let call = definition.call_object_function(
            &state_snapshot,
            object_id,
            function,
            args,
            rng_state,
            &global_view,
            self.physics,
            self.environment,
            self.frame,
            world,
            self.game_over_triggered,
            self.audio_registry.clone(),
        );
        let (value, outcome, audio_state, new_rng) = match call {
            Ok(ok) => ok,
            // Pre-error mutations persist (C++ mutated the live objects).
            Err(error) => {
                return Err(self.apply_script_error_recovery(
                    error,
                    index,
                    action_library,
                    object_id,
                    definition_id,
                    false,
                ));
            }
        };
        self.rng = new_rng;
        self.audio_registry = audio_state;
        self.apply_callback_outcome(
            index,
            outcome,
            action_library,
            object_id,
            definition_id,
            false,
        )?;
        Ok(value)
    }

    fn invoke_movement_hit_callbacks(
        &mut self,
        index: usize,
        old_velocity: FixedVec2,
        hit_speed_flags: u32,
        action_library: &ActionLibrary,
        object_id: ObjectId,
        definition_id: &str,
    ) -> Result<(), EngineError> {
        let args = [
            Value::Int(fixtoi_prec(old_velocity.x, 100)),
            Value::Int(fixtoi_prec(old_velocity.y, 100)),
        ];
        for (flag, function) in [
            (crate::ocf::HIT_SPEED1, "Hit"),
            (crate::ocf::HIT_SPEED2, "Hit2"),
            (crate::ocf::HIT_SPEED3, "Hit3"),
        ] {
            if hit_speed_flags & flag == 0 {
                continue;
            }
            // Engine-initiated lifecycle calls are fail-safe: a script
            // error in Hit/Hit2/Hit3 logs and the tick continues
            // (C4AulExec.cpp:1318-1342) — it must never kill the frame.
            if let Err(error) = self.call_movement_object_function(
                index,
                function,
                &args,
                action_library,
                object_id,
                definition_id,
            ) {
                tracing::warn!(
                    definition = %definition_id,
                    function,
                    %error,
                    "script error in engine callback; continuing like the C++ fail-safe exec"
                );
            }
        }
        Ok(())
    }

    pub fn handle_control_command(
        &mut self,
        owner: i32,
        command: ControlCommand,
        kind: CommandKind,
    ) -> Result<bool, EngineError> {
        let Some(function_name) = control_function_name(command, kind) else {
            return Ok(false);
        };

        self.ensure_cursor(owner)?;
        let Some(cursor) = self.crew_cursor(owner) else {
            return Ok(false);
        };

        let index = self
            .objects
            .iter()
            .position(|object| object.id == cursor)
            .ok_or(EngineError::UnknownObject(cursor))?;

        // C4Object::DirectCom (C4Object.cpp:3363-3367): a contained clonk
        // hands every non-Special com to its container and DirectCom
        // returns — the clonk's own Control<Com> is never consulted.
        if !matches!(command, ControlCommand::Special | ControlCommand::Special2) {
            if let Some(container) = self.objects[index].state.container {
                return self.contained_control(index, cursor, container, command, kind);
            }
        }

        let definition_id = self.objects[index].definition_id.clone();
        let state_snapshot = self.objects[index].script_state_snapshot();
        let definition = self
            .definitions
            .get(&definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?;
        let definitions_ref = &self.definitions;
        let action_library = definition.action_library().clone();
        let rng_state = self.rng.clone();
        let global_view = self.global_effects.clone();
        let world = self.host_world_context();
        let call = definition.call_control(
            &state_snapshot,
            cursor,
            &function_name,
            rng_state,
            &global_view,
            self.physics,
            self.environment,
            self.frame,
            world,
            self.game_over_triggered,
            self.audio_registry.clone(),
        );
        let (handled, outcome, audio_state, new_rng) = match call {
            Ok(ok) => ok,
            // Pre-error mutations persist (C++ mutated the live objects).
            Err(error) => {
                return Err(self.apply_script_error_recovery(
                    error,
                    index,
                    &action_library,
                    cursor,
                    &definition_id,
                    true,
                ));
            }
        };
        self.rng = new_rng;
        self.audio_registry = audio_state;
        self.apply_action_callback_outcome(
            index,
            outcome,
            &action_library,
            cursor,
            &definition_id,
        )?;
        Ok(handled)
    }

    /// C4Object::ContainedControl script dispatch (C4Object.cpp:3208-3306):
    /// the container's `Contained<Com>` function runs with the container as
    /// context and the clonk as parameter (`sf->Exec(Contained,
    /// {C4VObj(this)})`, :3221,3230) after the controller propagates
    /// (`Contained->Controller = Controller`, :3367). The com is consumed
    /// either way — DirectCom returns unconditionally. The hardcoded
    /// non-script fallbacks (COM_Down exit, COM_Throw command,
    /// COM_Up/COM_Dig base buy/sell, Take/Take2; :3243-3306) are command-AI
    /// features not yet ported — see PORT_STATUS.
    fn contained_control(
        &mut self,
        crew_index: usize,
        crew_id: ObjectId,
        container: ObjectId,
        command: ControlCommand,
        kind: CommandKind,
    ) -> Result<bool, EngineError> {
        let Some(container_index) = self.find_object_index(container) else {
            return Ok(true);
        };
        let controller = self.objects[crew_index].state.controller;
        self.objects[container_index].state.controller = controller;
        let Some(function) = com_name(command, kind).map(|com| format!("Contained{com}")) else {
            return Ok(true);
        };
        let definition_id = self.objects[container_index].definition_id.clone();
        let action_library = self
            .definitions
            .get(&definition_id)
            .ok_or_else(|| EngineError::UnknownDefinition(definition_id.clone()))?
            .action_library()
            .clone();
        let args = [compat::object_reference_value(crew_id)];
        self.call_movement_object_function(
            container_index,
            &function,
            &args,
            &action_library,
            container,
            &definition_id,
        )?;
        Ok(true)
    }

    pub fn try_grab_nearby(&mut self, owner: i32) -> Result<bool, EngineError> {
        self.ensure_cursor(owner)?;
        let Some(crew_id) = self.crew_cursor(owner) else {
            return Ok(false);
        };
        let crew_index = match self.find_object_index(crew_id) {
            Some(index) => index,
            None => return Err(EngineError::UnknownObject(crew_id)),
        };
        if !self.objects[crew_index].state.status.is_active() {
            return Ok(false);
        }
        let crew_position = self.objects[crew_index].state.position;
        let Some((_, target_id)) =
            self.find_nearby_object_with_mask(crew_id, crew_position, ocf::GRAB, 22, |object| {
                object.state.container.is_none() && object.state.status.is_active()
            })
        else {
            return Ok(false);
        };
        let update = ObjectUpdate::new()
            .with_container(crew_id)
            .with_position(crew_position)
            .with_velocity(Vector2::ZERO);
        self.apply_object_update(target_id, update)?;
        Ok(true)
    }

    pub fn try_drop_held_object(&mut self, owner: i32) -> Result<bool, EngineError> {
        self.ensure_cursor(owner)?;
        let Some(crew_id) = self.crew_cursor(owner) else {
            return Ok(false);
        };
        let crew_index = match self.find_object_index(crew_id) {
            Some(index) => index,
            None => return Err(EngineError::UnknownObject(crew_id)),
        };
        let crew_state = &self.objects[crew_index].state;
        if !crew_state.status.is_active() {
            return Ok(false);
        }
        let Some(item_id) = crew_state.contents.first().copied() else {
            return Ok(false);
        };
        let offset = match crew_state.direction {
            Direction::Left => -8,
            Direction::Right => 8,
            _ => 0,
        };
        let drop_position = Vector2::new(crew_state.position.x + offset, crew_state.position.y);
        let update = ObjectUpdate::new()
            .clear_container()
            .with_position(drop_position)
            .with_velocity(Vector2::ZERO);
        self.apply_object_update(item_id, update)?;
        // ObjectComDrop arms the dropper's NoCollectDelay and refreshes its
        // OCF after the exit (C4ObjectCom.cpp:668-671).
        if let Some(crew_index) = self.find_object_index(crew_id) {
            self.objects[crew_index].state.no_collect_delay = 2;
            self.refresh_object_ocf(crew_index);
        }
        Ok(true)
    }

    pub fn try_enter_nearby(&mut self, owner: i32) -> Result<bool, EngineError> {
        self.ensure_cursor(owner)?;
        let Some(crew_id) = self.crew_cursor(owner) else {
            return Ok(false);
        };
        let crew_index = match self.find_object_index(crew_id) {
            Some(index) => index,
            None => return Err(EngineError::UnknownObject(crew_id)),
        };
        let crew_state = &self.objects[crew_index].state;
        if crew_state.container.is_some() || !crew_state.status.is_active() {
            return Ok(false);
        }
        let crew_position = crew_state.position;
        let Some((target_index, target_id)) = self.find_nearby_object_with_mask(
            crew_id,
            crew_position,
            ocf::ENTRANCE,
            24,
            |object| object.state.status.is_active(),
        ) else {
            return Ok(false);
        };
        let target_position = self.objects[target_index].state.position;
        let update = ObjectUpdate::new()
            .with_container(target_id)
            .with_position(target_position)
            .with_velocity(Vector2::ZERO);
        self.apply_object_update(crew_id, update)?;
        Ok(true)
    }

    pub fn set_crew_role(
        &mut self,
        owner: i32,
        object_id: ObjectId,
        role: CrewRole,
    ) -> Result<(), EngineError> {
        if role.as_str().trim().is_empty() {
            return Err(EngineError::CrewRole {
                owner,
                detail: "role name must not be empty".to_string(),
            });
        }

        let object = self
            .objects
            .iter()
            .find(|object| object.id == object_id)
            .ok_or(EngineError::UnknownObject(object_id))?;
        if object.state.owner != owner {
            return Err(EngineError::CrewRole {
                owner,
                detail: format!("object {} is owned by {}", object_id, object.state.owner),
            });
        }
        if !object.state.crew_member {
            return Err(EngineError::CrewRole {
                owner,
                detail: format!("object {} is not a crew member", object_id),
            });
        }
        if !object.state.status.is_active() {
            return Err(EngineError::CrewRole {
                owner,
                detail: format!("object {} is not active", object_id),
            });
        }

        self.crew_roles
            .entry(owner)
            .or_default()
            .insert(object_id, role);
        Ok(())
    }

    pub fn crew_role(&self, owner: i32, object_id: ObjectId) -> Option<&CrewRole> {
        self.crew_roles
            .get(&owner)
            .and_then(|roles| roles.get(&object_id))
    }

    pub fn crew_role_assignments(&self, owner: i32) -> HashMap<ObjectId, CrewRole> {
        self.crew_roles.get(&owner).cloned().unwrap_or_default()
    }

    pub fn clear_crew_role(&mut self, owner: i32, object_id: ObjectId) {
        if let Some(assignments) = self.crew_roles.get_mut(&owner) {
            assignments.remove(&object_id);
            if assignments.is_empty() {
                self.crew_roles.remove(&owner);
            }
        }
    }

    pub fn clear_roles_for_owner(&mut self, owner: i32) {
        self.crew_roles.remove(&owner);
    }

    pub fn apply_command(
        &mut self,
        owner: i32,
        target: CrewCommandTarget,
        update: ObjectUpdate,
    ) -> Result<(), EngineError> {
        self.prune_roles();
        let mut recipients = self.resolve_command_targets(owner, &target);
        if recipients.is_empty() {
            return Ok(());
        }

        let mut seen = HashSet::new();
        recipients.retain(|id| seen.insert(*id));
        if recipients.len() > 1 {
            let ordering: HashMap<_, _> = self
                .objects
                .iter()
                .enumerate()
                .map(|(index, object)| (object.id, index))
                .collect();
            recipients.sort_by_key(|id| ordering.get(id).copied().unwrap_or(usize::MAX));
        }
        for object_id in recipients {
            self.apply_object_update(object_id, update.clone())?;
        }
        Ok(())
    }

    pub fn global_effects(&self) -> &[EffectState] {
        &self.global_effects
    }

    pub fn register_definition(&mut self, definition: Definition) -> Result<(), EngineError> {
        let id = definition.id().to_string();
        if self.definitions.contains_key(&id) {
            return Err(EngineError::DefinitionAlreadyExists(id));
        }

        let mut definition = definition;
        {
            // One GlobalNamed table for every script host: `static`
            // declarations compiled into the definition move to it.
            let script = Arc::make_mut(&mut definition.script);
            script.set_global_variables(self.script_globals.clone());
            script.set_global_slots(self.script_global_slots.clone());
            script.set_global_constants(self.script_global_consts.clone());
            script.adopt_statics_into_globals();
        }

        // A def script's `global func`s land on the ENGINE scope like any
        // System.c4g global (C4AulParse "global" storage — the GoldRush
        // Talker's StartMovie is called from the scenario script). C4Aul
        // also leaves a FnLink in the declaring definition; repoint the
        // local copy at the engine-chained function so inherited() follows
        // OwnerOverloaded without later definitions stealing this link.
        let def_globals: Vec<(String, lc_script::Function)> = definition
            .script
            .global_access_functions()
            .map(|(name, function)| (name.clone(), function.clone()))
            .collect();
        if !def_globals.is_empty() {
            let mut functions: HashMap<String, lc_script::Function> = self
                .global_script_functions
                .as_deref()
                .cloned()
                .unwrap_or_default();
            for (function_name, mut function) in def_globals {
                if let Some(previous) = functions.remove(&function_name) {
                    function.push_overload(previous);
                }
                Arc::make_mut(&mut definition.script)
                    .link_global_access_function(&function_name, function.clone());
                functions.insert(function_name, function);
            }
            let table = Some(Arc::new(functions));
            self.global_script_functions = table.clone();
            for existing in self.definitions.values_mut() {
                existing.set_global_functions(table.clone());
            }
            if let Some(script) = self.scenario_script.as_mut() {
                script.set_global_functions(table.clone());
            }
        }
        definition.set_global_functions(self.global_script_functions.clone());
        let definition_id = DefinitionId::from(id.as_str());
        if !definition.appends.is_empty() {
            self.append_script_sources
                .push(AppendScriptSource::Definition(definition_id.clone()));
        }
        self.definition_load_order.push(definition_id.clone());
        let runtime_order = Rc::make_mut(&mut self.runtime_definition_order);
        runtime_order.push(definition_id);
        runtime_order.sort_unstable_by_key(|id| {
            definition_id_to_c4id(id.as_str())
                .map(|id| id as u32)
                .unwrap_or_default()
        });
        self.definitions.insert(id, definition);
        self.definition_metadata_cache.borrow_mut().take();
        self.solid_mask_metadata_cache.borrow_mut().take();
        Ok(())
    }

    /// Installs the engine-global script functions — the System.c4g
    /// `global func`s that C++ owns on `Game.ScriptEngine`
    /// (resolution per FindSameNameFunc: own-def script first, engine-owned
    /// fallback, C4Aul.cpp:130-148). Scripts that fail to compile log and
    /// are skipped like C++. The table is shared into every registered
    /// (and future) script host.
    pub fn install_global_scripts(&mut self, sources: &[(String, String)]) -> usize {
        self.global_script_functions = None;
        self.append_script_sources.clear();
        self.install_additional_global_scripts(sources)
    }

    /// Adds global scripts ON TOP of the installed table: later definitions
    /// overload earlier ones and `inherited` reaches them (C++ link order —
    /// the scenario's System.c4g joins the engine's, C4Game.cpp:3317-3343).
    pub fn install_additional_global_scripts(&mut self, sources: &[(String, String)]) -> usize {
        self.install_global_scripts_at(sources)
    }

    /// Installs scenario-local System.c4g after all definitions, matching the
    /// explicit C++ overload-priority phase (C4Game.cpp:2606-2617).
    pub fn install_scenario_global_scripts(&mut self, sources: &[(String, String)]) -> usize {
        self.install_global_scripts_at(sources)
    }

    fn install_global_scripts_at(&mut self, sources: &[(String, String)]) -> usize {
        let mut functions: HashMap<String, lc_script::Function> = self
            .global_script_functions
            .as_deref()
            .cloned()
            .unwrap_or_default();
        let mut loaded = 0usize;
        for (name, source) in sources {
            match lc_script::Script::compile(source) {
                Ok(script) => {
                    // System/scenario System.c4g declarations participate in
                    // the same engine-global GlobalNamed/GlobalConsts tables
                    // as definition scripts (C4Aul preparser and
                    // RegisterGlobalConstant, C4Aul.cpp:484-492).
                    lc_script::register_global_declarations(
                        script.var_decls(),
                        &self.script_globals,
                        Some(&self.script_global_consts),
                    );
                    // Scripts with #appendto also append their functions to
                    // the named definitions at link time (C4AulLink.cpp:
                    // 29-64). Statics were registered above and AppendTo
                    // copies LocalNamed only (:145-157).
                    if !script.appends().is_empty() {
                        let append_script = script.clone().without_static_declarations();
                        self.append_script_sources
                            .push(AppendScriptSource::Script(append_script));
                    }
                    for (function_name, function) in script.global_access_functions() {
                        let mut function = function.clone();
                        if let Some(previous) = functions.remove(function_name) {
                            function.push_overload(previous);
                        }
                        functions.insert(function_name.clone(), function);
                    }
                    loaded += 1;
                }
                Err(error) => {
                    tracing::warn!(
                        script = %name,
                        %error,
                        "global script failed to compile; skipping like C++"
                    );
                }
            }
        }
        let table = (!functions.is_empty()).then(|| Arc::new(functions));
        self.global_script_functions = table.clone();
        for definition in self.definitions.values_mut() {
            definition.set_global_functions(table.clone());
        }
        if let Some(script) = self.scenario_script.as_mut() {
            script.set_global_functions(table.clone());
        }
        loaded
    }

    /// `C4AulScript::ResolveAppends` (C4AulLink.cpp:29-64): every script's
    /// `#appendto` targets receive a COPY of its non-global functions as
    /// overrides (AppendTo with bHighPrio, :114-141). MUST run before
    /// include resolution (":27-28 ResolveAppends has to be called
    /// first!"). Sources follow the single script-host registration order:
    /// definition-pack System hosts stay interleaved with definitions, then
    /// scenario Script.c and scenario System.c4g follow (C4Def.cpp:927-968;
    /// C4Game.cpp:2606-2617). That order decides the overload chain when
    /// several appends hit the same target function. Unknown targets warn and skip
    /// (:42-49); `#appendto *` reaches every definition except the source
    /// (:53-60).
    pub fn resolve_appends(&mut self) {
        if self.append_script_sources.is_empty() {
            return;
        }

        let ordered_ids = self.definition_load_order.clone();
        for source in self.append_script_sources.clone() {
            let (source_script, source_id, targets) = match source {
                AppendScriptSource::Script(script) => {
                    let mut engine = ScriptEngine::new();
                    engine.set_global_variables(self.script_globals.clone());
                    engine.set_global_slots(self.script_global_slots.clone());
                    engine.set_global_constants(self.script_global_consts.clone());
                    let targets = script.appends().to_vec();
                    engine.add_script(script);
                    #[allow(clippy::arc_with_non_send_sync)] // single-threaded sharing
                    (Arc::new(engine), None, targets)
                }
                AppendScriptSource::Definition(id) => match self.definitions.get(&id) {
                    Some(definition) => (
                        definition.script.clone(),
                        Some(id),
                        definition.appends.clone(),
                    ),
                    None => continue,
                },
            };
            for target in targets {
                let resolved: Vec<DefinitionId> = match &target {
                    lc_script::AppendTo::Id(token) => {
                        let id = DefinitionId::from(token.as_str());
                        if self.definitions.contains_key(&id) {
                            vec![id]
                        } else {
                            // "script to #appendto not found"
                            // (C4AulLink.cpp:42-49) — a warning, never an
                            // error.
                            tracing::warn!(target = %token, "script to #appendto not found");
                            Vec::new()
                        }
                    }
                    lc_script::AppendTo::Wildcard => ordered_ids
                        .iter()
                        .filter(|id| Some(*id) != source_id.as_ref())
                        .cloned()
                        .collect(),
                };
                for target_id in resolved {
                    if let Some(definition) = self.definitions.get_mut(&target_id) {
                        Arc::make_mut(&mut definition.script).append_overrides_from(&source_script);
                        definition.refresh_script_flags();
                    }
                }
            }
        }
        self.definition_metadata_cache.borrow_mut().take();
        self.solid_mask_metadata_cache.borrow_mut().take();
    }

    /// Registers `global func` declarations from DEFINITION scripts into
    /// the engine-global table (C4Aul AA_GLOBAL functions are owned by
    /// Game.ScriptEngine — Time.c4d's IsNight, MainTipi's GetClan):
    /// applied on top of the installed System.c4g table in definition
    /// load order, later declarations overloading earlier ones, then
    /// re-shared to every script host.
    pub fn collect_definition_global_functions(&mut self) {
        let mut functions: HashMap<String, lc_script::Function> = self
            .global_script_functions
            .as_deref()
            .cloned()
            .unwrap_or_default();
        let mut changed = false;
        for id in &self.definition_load_order {
            let Some(definition) = self.definitions.get(id) else {
                continue;
            };
            for (name, function) in definition.script.global_access_functions() {
                let mut function = function.clone();
                if let Some(previous) = functions.remove(name) {
                    function.push_overload(previous);
                }
                functions.insert(name.clone(), function);
                changed = true;
            }
        }
        if !changed {
            return;
        }
        let table = Some(Arc::new(functions));
        self.global_script_functions = table.clone();
        for definition in self.definitions.values_mut() {
            definition.set_global_functions(table.clone());
        }
        if let Some(script) = self.scenario_script.as_mut() {
            script.set_global_functions(table.clone());
        }
        self.definition_metadata_cache.borrow_mut().take();
        self.solid_mask_metadata_cache.borrow_mut().take();
    }

    pub fn resolve_includes(&mut self) -> Result<(), EngineError> {
        self.definition_metadata_cache.borrow_mut().take();
        self.solid_mask_metadata_cache.borrow_mut().take();
        // Iteratively merge includes until no more changes occur
        // This ensures transitive dependencies are fully resolved
        // (e.g., TRE2 -> TRE1 -> TREE means TRE2 gets functions from TREE)
        let mut changed = true;

        while changed {
            changed = false;

            // Collect all definitions that have includes
            let ids_with_includes: Vec<String> = self
                .definitions
                .iter()
                .filter(|(_, def)| !def.includes().is_empty())
                .map(|(id, _)| id.clone())
                .collect();

            // For each definition with includes, merge parent functions
            for child_id in ids_with_includes {
                let includes = self
                    .definitions
                    .get(&child_id)
                    .map(|def| def.includes().to_vec())
                    .unwrap_or_default();
                let (before_rank_image, before_rank_count) = self
                    .definitions
                    .get(&child_id)
                    .map(|definition| {
                        (
                            definition.rank_symbols_image.clone(),
                            definition.rank_symbol_count,
                        )
                    })
                    .unwrap_or((None, None));

                for parent_id in &includes {
                    // Check if parent exists
                    if !self.definitions.contains_key(parent_id) {
                        return Err(EngineError::UnknownDefinition(parent_id.clone()));
                    }

                    // Clone the parent to avoid borrow checker issues
                    let parent = self.definitions.get(parent_id).unwrap().clone();

                    // Count functions before merge to detect changes
                    let before_count = self
                        .definitions
                        .get(&child_id)
                        .map(|def| def.function_count())
                        .unwrap_or(0);
                    // Merge parent into child
                    if let Some(child) = self.definitions.get_mut(&child_id) {
                        child.merge_from(&parent);

                        // Check if we added any functions
                        let after_count = child.function_count();
                        if after_count > before_count {
                            changed = true;
                        }
                    }
                }
                if let Some(child) = self.definitions.get(&child_id) {
                    let same_rank_image = match (
                        before_rank_image.as_ref(),
                        child.rank_symbols_image.as_ref(),
                    ) {
                        (Some(before), Some(after)) => before.shares_storage_with(after),
                        (None, None) => true,
                        _ => false,
                    };
                    if !same_rank_image || before_rank_count != child.rank_symbol_count {
                        changed = true;
                    }
                }
            }
        }

        Ok(())
    }

